// Junta el calendario de GitHub con los canales de Buffer y prepara un post por canal
const cal = $('Leer calendario (GitHub)').first().json;
const chans = $('Buffer: canales').first().json.data.channels;
const now = Date.now() + 10 * 60 * 1000; // solo posts al menos 10 min en el futuro
const out = [];
const mutation = `mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    __typename
    ... on PostActionSuccess { post { id dueAt } }
    ... on MutationError { message }
  }
}`;
for (const p of cal.posts) {
  if (new Date(p.dueAt).getTime() < now) continue;
  for (const c of chans) {
    const s = (c.service || '').toLowerCase();
    let metadata = null;
    if (s === 'youtube') metadata = { youtube: { title: p.title, privacy: 'public', categoryId: '27', madeForKids: false, notifySubscribers: true } };
    else if (s === 'instagram') metadata = { instagram: { type: 'reel', shouldShareToFeed: true } };
    else if (s === 'tiktok') metadata = { tiktok: { title: p.title } };
    else if (s === 'facebook') metadata = { facebook: { type: 'reel' } };
    else continue;
    const input = {
      channelId: c.id, text: p.text, schedulingType: 'automatic', mode: 'customScheduled',
      dueAt: p.dueAt, assets: [{ video: { url: p.video } }], metadata
    };
    out.push({ json: { ep: p.ep, channel: c.service + ' · ' + (c.displayName || c.name), dueAt: p.dueAt,
                       body: { query: mutation, variables: { input } } } });
  }
}
if (out.length === 0) return [{ json: { aviso: 'No hay posts futuros en el calendario' } }];
return out;
